use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames();
    let len = frames.len();
    var total = 0;
    var i = 0;
    while i < len {
        let frame = match frames.get(i) {
            Some(f) => f,
            None => "",
        };
        let count = match relay.feed.decode(frame) {
            Ok(n) => n,
            Err(_) => 0,
        };
        total = total + count;
        i = i + 1;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

use harbor.signal;

pub fn entries() -> String {
    let signals = harbor.signal.sequence();
    var rendered: List<String> = [];
    var i = 0;
    while i < signals.len() {
        match signals.get(i) {
            Some(sig) => {
                let entry = match sig {
                    Calm => "calm",
                    Gale(speed) => "gale:".concat(other: speed.to_text()),
                    Fog(density) => "fog:".concat(other: density),
                };
                rendered.push(entry);
            },
            None => {},
        }
        i = i + 1;
    }
    rendered.join(";")
}

