use mill.stock;
use mill.rules;

pub fn lines() -> String {
    let planks = mill.stock.inventory();
    var labels: List<String> = [];
    var i = 0;
    while i < planks.len() {
        match planks.get(i) {
            Some(plank) => {
                if mill.rules.keeps(plank) {
                    labels.push(mill.rules.label(plank));
                }
            },
            None => {},
        }
        i = i + 1;
    }
    labels.join(",")
}
